    Assert.assertEquals(true, getBoolField(spout, "fileReadCompletely"));
    //ack rest
    runSpout(spout, "a3", "a4");
    reader = getField(spout, "reader");
    Assert.assertNull(reader);
    Assert.assertEquals(true, getBoolField(spout, "fileReadCompletely"));
