        Time.advanceTime((expectedWaitTime + 1L) / 2L);
        assertFalse("message should not be ready for retry yet", manager.shouldReEmitMsg(TEST_OFFSET));
        Time.advanceTime((expectedWaitTime + 1L) / 2L);
