        assertTrue("message should be ready for retry", manager.shouldReEmitMsg(TEST_OFFSET));
        manager.retryStarted(TEST_OFFSET);
        expectedWaitTime = Math.min((long) (expectedWaitTime * mult), max);
    }
}

