@Test
public void testScanStop() throws Exception {
    final Set<Integer> eventsScanned = new HashSet<>();
    EvictionPolicy<Integer> evictionPolicy = new WatermarkTimeEvictionPolicy<Integer>(20, 5) {

        @Override
        public Action evict(Event<Integer> event) {
            eventsScanned.add(event.get());
            return super.evict(event);
        }
    };
    windowManager.setEvictionPolicy(evictionPolicy);
    TriggerPolicy<Integer> triggerPolicy = new WatermarkTimeTriggerPolicy<Integer>(10, windowManager, evictionPolicy, windowManager);
    triggerPolicy.start();
    windowManager.setTriggerPolicy(triggerPolicy);
    windowManager.add(1, 603);
    windowManager.add(2, 605);
    windowManager.add(3, 607);
    windowManager.add(4, 618);
    windowManager.add(5, 626);
    windowManager.add(6, 629);
    windowManager.add(7, 636);
    windowManager.add(8, 637);
    windowManager.add(9, 638);
    windowManager.add(10, 639);
    // send a watermark event, which should trigger three windows.
    windowManager.add(new WaterMarkEvent<Integer>(631));
    assertEquals(3, listener.allOnActivationEvents.size());
    assertEquals(seq(1, 3), listener.allOnActivationEvents.get(0));
    assertEquals(seq(1, 4), listener.allOnActivationEvents.get(1));
    // out of order events should be processed upto the lag
    assertEquals(Arrays.asList(4, 5, 6), listener.allOnActivationEvents.get(2));
    // events 8, 9, 10 should not be scanned at all since TimeEvictionPolicy lag 5s should break
    // the WindowManager scan loop early.
    assertEquals(new HashSet<>(seq(1, 7)), eventsScanned);
}

@Test
public void testGoodThrift() throws Exception {
    int drpcPort = Utils.getAvailablePort();
    int invocationsPort = Utils.getAvailablePort(drpcPort + 1);
    Map<String, Object> conf = getConf(drpcPort, invocationsPort, null);
    try (DRPCServer server = new DRPCServer(conf)) {
        exec.submit(() -> {
            server.start();
            return null;
        });
        try (DRPCClient client = new DRPCClient(conf, "localhost", drpcPort);
            DRPCInvocationsClient invoke = new DRPCInvocationsClient(conf, "localhost", invocationsPort)) {
            Future<String> found = exec.submit(() -> client.getClient().execute("testing", "test"));
            DRPCRequest request = getNextAvailableRequest(invoke, "testing");
            assertNotNull(request);
            assertEquals("test", request.get_func_args());
            assertNotNull(request.get_request_id());
            invoke.result(request.get_request_id(), "tested");
            String result = found.get(1000, TimeUnit.MILLISECONDS);
            assertEquals("tested", result);
        }
    }
}

@Test
public void testFailedThrift() throws Exception {
    int drpcPort = Utils.getAvailablePort();
    int invocationsPort = Utils.getAvailablePort(drpcPort + 1);
    Map<String, Object> conf = getConf(drpcPort, invocationsPort, null);
    try (DRPCServer server = new DRPCServer(conf)) {
        exec.submit(() -> {
            server.start();
            return null;
        });
        try (DRPCClient client = new DRPCClient(conf, "localhost", drpcPort);
            DRPCInvocationsClient invoke = new DRPCInvocationsClient(conf, "localhost", invocationsPort)) {
            Future<String> found = exec.submit(() -> client.getClient().execute("testing", "test"));
            DRPCRequest request = getNextAvailableRequest(invoke, "testing");
            assertNotNull(request);
            assertEquals("test", request.get_func_args());
            assertNotNull(request.get_request_id());
            invoke.failRequest(request.get_request_id());
            try {
                found.get(1000, TimeUnit.MILLISECONDS);
                fail("exec did not throw an exception");
            } catch (ExecutionException e) {
                Throwable t = e.getCause();
                assertEquals(t.getClass(), DRPCExecutionException.class);
                //Don't know a better way to validate that it failed.
                assertEquals("Request failed", ((DRPCExecutionException) t).get_msg());
            }
        }
    }
}

